#define NG 3
#define NJ 8
#define NP 16
static HSD_GObj GO[NG];
static HSD_JObj JO[NJ];
static Fighter FT[NG];
static ftData FDATA[NG];
static FighterBone PARTS[NG][64];
static ftCommonData CD;
static HSD_GObj* PLINKV[16];
static u8 PADB[96][2048];

static HSD_GObj* pick_HSD_GObj(void) { u32 r = rnd(); return (r % 6) == 0 ? 0 : &GO[(r >> 8) % NG]; }
static HSD_JObj* pick_HSD_JObj(void) { u32 r = rnd(); return (r % 6) == 0 ? 0 : &JO[(r >> 8) % NJ]; }
static Fighter* pick_Fighter(void) { u32 r = rnd(); return (r % 6) == 0 ? 0 : &FT[(r >> 8) % NG]; }
static Item* pick_Item(void) { return 0; }
static HSD_DObj* pick_HSD_DObj(void) { return 0; }
static void cbev1(HSD_GObj* g) { T(7001); T(PI(g)); }
static void cbev2(HSD_GObj* g) { T(7002); T(PI(g)); }
static int cbp1(HSD_GObj* g) { T(7003); T(PI(g)); return (int) (fv() & 1); }
static int cbp2(HSD_GObj* g) { T(7004); T(PI(g)); return (int) (fv() & 1); }
static void cbev3(HSD_GObj* g, HSD_GObj* h) { T(7005); T(PI(g)); T(PI(h)); }
static void* pick_fn(int kind)
{
    u32 r = rnd();
    if ((r & 3) == 0) return 0;
    switch (kind) {
    case 1: return (r & 4) ? (void*) cbev1 : (void*) cbev2;
    case 2: return (r & 4) ? (void*) cbp1 : (void*) cbp2;
    case 3: return (void*) cbev3;
    }
    return 0;
}
static void* pick_cb(int kind) { void* f = pick_fn(kind); return f ? f : (kind == 2 ? (void*) cbp1 : kind == 3 ? (void*) cbev3 : (void*) cbev1); }

static ftDynamics DYN[NG]; static ArticleDynamicBones ADB[NG]; static struct DynamicsData DDP[NG][Ft_Dynamics_NumMax][3];
static FigaTree** X10[NG][5]; static FigaTree* TREES[NG][4][Ft_Dynamics_NumMax]; static u8 X28A[NG][8][2]; static u8 ARG1[2]; static int SGK;
static void HF(float f) { union { float f; u32 u; } c; c.f = f; HM(c.u); }
#include "ftdynamics_stubs.h"
#include "ftdynamics_state.h"
HSD_GObj** HSD_GObjPLinkHead;   /* tentative: the stub header defines it only for TUs that read it */
ftCommonData* p_ftCommonData;
StageInfo stage_info;

static void world(void)
{
    int i, b;
    zero(GO, sizeof GO); zero(JO, sizeof JO); zero(FT, sizeof FT); zero(FDATA, sizeof FDATA); zero(&CD, sizeof CD);
    for (i = 0; i < NG; i++) fill_Fighter(&FT[i]);
    for (i = 0; i < NJ; i++) fill_HSD_JObj(&JO[i]);
    for (i = 0; i < NG; i++) fill_HSD_GObj(&GO[i]);
    for (i = 0; i < NG; i++) {
        GO[i].user_data = &FT[i];
        GO[i].hsd_obj = &JO[i];
        GO[i].classifier = HSD_GOBJ_CLASS_FIGHTER;
        GO[i].next = i + 1 < NG ? &GO[i + 1] : 0;
        FT[i].gobj = &GO[i];
        FT[i].ft_data = &FDATA[i];
        FT[i].grab_cb = cbev1; FT[i].grabbed_cb = cbev3;
        FT[i].kind = (FighterKind) ((u32) FT[i].kind % 27u); FT[i].player_id %= 4; FT[i].x618_player_id %= 4;
        for (b = 0; b < 64; b++) { if (b < NP) fill_FighterBone(&PARTS[i][b]); else { zero(&PARTS[i][b], sizeof PARTS[i][b]); PARTS[i][b].flags_b1 = 1; } PARTS[i][b].joint = &JO[(u32) (i * 5 + b * 3) % NJ]; }
        FT[i].parts = PARTS[i];
        { int pk = i * 24; FDATA[i].x0 = (void*) PADB[pk++]; FDATA[i].ext_attr = (void*) PADB[pk++]; FDATA[i].x8 = (void*) PADB[pk++]; FDATA[i].xC = (void*) PADB[pk++]; FDATA[i].x10 = (void*) PADB[pk++]; FDATA[i].x14 = (void*) PADB[pk++]; FDATA[i].x18 = (void*) PADB[pk++]; FDATA[i].x1C = (void*) PADB[pk++]; FDATA[i].x20 = (void*) PADB[pk++]; FDATA[i].x24 = (void*) PADB[pk++]; FDATA[i].x28 = (void*) PADB[pk++]; FDATA[i].x2C = (void*) PADB[pk++]; FDATA[i].x30 = (void*) PADB[pk++]; FDATA[i].x34 = (void*) PADB[pk++]; FDATA[i].x38 = (void*) PADB[pk++]; FDATA[i].x3C = (void*) PADB[pk++]; FDATA[i].x40 = (void*) PADB[pk++]; FDATA[i].x44 = (void*) PADB[pk++]; FDATA[i].x48_items = (void*) PADB[pk++]; FDATA[i].x4C_sfx = (void*) PADB[pk++]; FDATA[i].x50 = (void*) PADB[pk++]; FDATA[i].x54 = (void*) PADB[pk++]; FDATA[i].x58 = (void*) PADB[pk++]; FDATA[i].x5C = (void*) PADB[pk++]; }
    }
    for (i = 0; i < NJ; i++) {
        JO[i].parent = i ? &JO[(i - 1) / 2] : 0;
        JO[i].child = 2 * i + 1 < NJ ? &JO[2 * i + 1] : 0;
        JO[i].next = (i & 1) && i + 1 < NJ ? &JO[i + 1] : 0;
    }
    p_ftCommonData = &CD;
    for (i = 0; i < 16; i++) PLINKV[i] = 0;
    PLINKV[HSD_GOBJ_PLINK_FIGHTER] = &GO[0];
    HSD_GObjPLinkHead = PLINKV;
    { int q_, k_, j_, a_;
      SGK = (fv() & 1) ? Gr_Kind_Flatzone : 0; stage_info.grkind = SGK;
      for (q_ = 0; q_ < NG; q_++) {
        zero(&DYN[q_], sizeof DYN[q_]); zero(&ADB[q_], sizeof ADB[q_]); zero(&DDP[q_], sizeof DDP[q_]);
        DYN[q_].dynamicsNum = (int) (fv() % 10); DYN[q_].ftDynamicBones = &ADB[q_];
        for (k_ = 0; k_ < Ft_Dynamics_NumMax; k_++) {
          ADB[q_].array[k_].bone_id = fv() % 60; ADB[q_].array[k_].dyn_desc.count = fv() % 5;
          for (j_ = 0; j_ < 3; j_++) {
            struct DynamicsData* d_ = &DDP[q_][k_][j_];
            d_->next = (j_ < 2 && (fv() & 1)) ? &DDP[q_][k_][j_ + 1] : 0;
            d_->desc.lb_unk0.jobj = &JO[fv() % NJ];
            d_->desc.lb_unk0.translate.x = rg(); d_->desc.lb_unk0.translate.y = rg(); d_->desc.lb_unk0.translate.z = rg();
            d_->desc.lb_unk0.scale.x = rg(); d_->desc.lb_unk0.scale.y = rg(); d_->desc.lb_unk0.scale.z = rg();
          }
          FT[q_].dynamic_bone_sets[k_].dyn_desc.data = &DDP[q_][k_][0];
        }
        FDATA[q_].x2C = &DYN[q_];
        FT[q_].dynamics_num = (int) (fv() % 11);
        for (a_ = 0; a_ < 4; a_++) {
          for (k_ = 0; k_ < Ft_Dynamics_NumMax; k_++) TREES[q_][a_][k_] = (FigaTree*) (size_t) (fv() % 4);
          X10[q_][a_] = (fv() % 5 == 0) ? 0 : TREES[q_][a_];
        }
        X10[q_][4] = 0;
        DYN[q_].x10 = X10[q_];
        FT[q_].x28 = &X28A[q_][1];
        for (a_ = 0; a_ < 8; a_++) { X28A[q_][a_][0] = fv() % 256; X28A[q_][a_][1] = fv() % 5; }
        FT[q_].anim_id = (int) (fv() % 7) - 1;
        if (fv() & 1) FT[q_].x34_scale.y = 1.0f;
        FT[q_].x594_b3 = fv() & 1; FT[q_].x594_b4 = fv() & 1;
      }
      ARG1[0] = fv() % 256; ARG1[1] = fv() % 5;
    }
}
static void hworld(void)
{
    int i, b;
    for (i = 0; i < NG; i++) hash_Fighter(&FT[i]);
    for (i = 0; i < NJ; i++) hash_HSD_JObj(&JO[i]);
    for (i = 0; i < NG; i++) hash_HSD_GObj(&GO[i]);
    for (i = 0; i < NG; i++) for (b = 0; b < NP; b++) hash_FighterBone(&PARTS[i][b]);
    { int q_, k_, j_; for (q_ = 0; q_ < NG; q_++) for (k_ = 0; k_ < Ft_Dynamics_NumMax; k_++) for (j_ = 0; j_ < 3; j_++) { struct DynamicsData* d_ = &DDP[q_][k_][j_];
        HF(d_->desc.lb_unk0.unk_2C.x); HF(d_->desc.lb_unk0.unk_2C.y); HF(d_->desc.lb_unk0.unk_2C.z); HF(d_->desc.lb_unk0.unk_44); HF(d_->desc.lb_unk0.translate.x); HF(d_->desc.lb_unk0.scale.x); } }
}

int main(void)
{
    int op, k;
    preg(GO, sizeof GO); preg(JO, sizeof JO); preg(FT, sizeof FT); preg(FDATA, sizeof FDATA); preg(PADB, sizeof PADB);
    freg((const void*) cbev1); freg((const void*) cbev2); freg((const void*) cbp1); freg((const void*) cbp2); freg((const void*) cbev3);
    for (op = 0; op < 5; op++) {
        for (k = 0; k < 500; k++) {
            u32 ret = 0;
            tu_case(op, k);
            world();
            ASRT_ARMED = 1;
            if (_setjmp(ASRT_JB, 0) != 0) { printf("%d %d ASSERT%c", op, k, 10); fflush(0); continue; }
            {
                int gi = (int) (rnd() % NG);
                Fighter_GObj* g = &GO[gi];
                Fighter* fp = &FT[gi];
                (void) g; (void) fp;
                switch (op) {
                case 0: ftCo_8009CF84(fp); break;
                case 1: ftCo_8009DD94(g, (bool)(fv() & 1)); break;
                case 2: ftCo_8009E0A8(g); break;
                case 3: ftCo_8009E614(fp); break;
                case 4: ftCo_8009E7B4(fp, (u8(*)[2]) ARG1); break;
                }
            }
            hworld();
            ASRT_ARMED = 0;
            printf("%d %d %08X %08X %08X\n", op, k, ret, H, TR);
            fflush(0);
        }
    }
    return 0;
}
